import json,pathlib,hashlib,datetime,sys
P=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(P/'scripts'));from validate import question_hash,schema_errors
A=P/'audits';b=json.load(open(P/'data/question-batches/W11-L52.json'));blind=json.load(open(A/'blind-answers-W11-L52-v2-integration.json'));binding=json.load(open(A/'blind-binding-W11-L52-v2.json'));hashes={x['id']:x['sha256'] for x in binding['questions']};manifest=json.load(open(A/'W11-L52-v2-repair-manifest.json'));by={x['questionId']:x for x in blind['answers']};now=datetime.datetime.now(datetime.timezone.utc).isoformat();rid=blind['reviewerId'];bh=hashlib.sha256((A/'blind-answers-W11-L52-v2-integration.json').read_bytes()).hexdigest();rows=[]
