s={'completedAt':now,'reviewed':len(rows),'verified':len(rows),'flagged':0,'acceptedPreserved':117,'lectureVerified':138,'actualReviewPagesInspected':blind['actualPagesInspected'],'acceptedQuestionHashes':{q['id']:question_hash(q) for q in b['questions']},'reviewPath':str(f.relative_to(P)),'reviewSha256':hashlib.sha256(f.read_bytes()).hexdigest(),'blindAnswersSha256':bh,'gapDispositions':manifest['gapQuestionMap'],'coverageConclusion':'The21current repair/gap items are accepted and117prioraccepted hashes are unchanged. The six original bounded construction/interface/tactile/selection gaps are closed. This review inspected20changed cited pages; prior independent full65-page coverage remains separately recorded.','sourceQualificationSha256':manifest['sourceQualificationSha256'],'sourceQualificationCount':manifest['sourceQualificationCount'],'externalEvidenceChecked':[{'url':'https://www.st.com/resource/en/user_manual/um2039-world-smallest-timeofflight-ranging-and-gesture-detection-sensor-application-programming-interface-stmicroelectronics.pdf','locator':'Table1physicalpage16','checkedAt':now},{'url':'https://github.com/arduino/reference-en/blob/master/Language/Variables/Variable%20Scope%20%26%20Qualifiers/volatile.adoc','locator':'int or long volatiles','checkedAt':now}]}
(A/'W11-L52-v2-integration-review-summary.json').write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:s[k] for k in ['reviewed','verified','flagged','lectureVerified','reviewSha256']}))
